{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this production plan — for example, maximize the number of complete products (each requiring one of each component) that can be produced, minimize total production hours used, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting examples as options for that one decision."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are there any demand limits or minimum production requirements for the components, or is the only constraint the workshop capacity (i.e., we can produce as many components as the workshops allow, up to what's needed for complete products)?"
  ],
  "rationale": "The response asks a single clarification question regarding the nature of constraints (demand/minimums vs. capacity only), presented as a single choice between two scenarios."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Can a workshop split its available hours across multiple components (e.g., Workshop A uses 40 hours on Component 1 and 60 hours on Component 2), or must each workshop dedicate all its hours to a single component?"
  ],
  "rationale": "The response asks for a single policy choice regarding how workshop hours are allocated, which constitutes one semantically independent question."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Are the production rates constant regardless of how many hours a workshop spends on a component (i.e., linear: units = rate × hours), or are there any setup times, batch requirements, or other nonlinear effects I should account for?"
  ],
  "rationale": "The response asks a single clarification question regarding the linearity of production rates versus the presence of nonlinear effects like setup times or batch requirements."
}

{
  "action": "question",
  "question_count": 1,
