  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding the granularity of hours."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do the final number of complete products need to be a whole number, or is it acceptable for the model to report a fractional value (e.g., 123.4 products)?"
  ],
  "rationale": "The response contains a single clarification question asking for a policy choice regarding integer vs. fractional constraints."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "If the model produces, say, 123.4 complete products, should I round down to 123 (i.e., only count fully assembled products), or is there any other way you'd like the final integer value determined?"
  ],
  "rationale": "The response asks for a single policy decision regarding how to handle fractional output values (rounding down vs. other methods)."
}

